                            style={{
                              color: onTransparent ? "rgba(255,255,255,0.95)" : "rgba(20,21,23,0.88)",
                            }}
                          >
                            {item.label}
                          </Link>
                        ))}
                      </div>
                    </motion.div>
                  )}
                </AnimatePresence>
              </div>
            );
          })}
        </nav>

        {/* Right Section */}
        <div className="flex items-center gap-5">
          <motion.button
