    transition: { when: "beforeChildren", staggerChildren: 0.06, duration: 0.28, ease: EASE_CB },
  },
};

const item: Variants = {
  hidden: { opacity: 0, y: 10 },
  show: { opacity: 1, y: 0, transition: { type: "spring", stiffness: 220, damping: 24, mass: 0.7 } },
};

function isHttpUrl(src?: string) {
  return !!src && (src.startsWith("http://") || src.startsWith("https://"));
}

// Safe, loose access helper without `any`
const loose = (o: unknown): Record<string, unknown> =>
  typeof o === "object" && o !== null ? (o as Record<string, unknown>) : {};

type Props = {
  initialPosts?: BlogPost[];
  pageSize?: number;
  placeholderImage?: string;
  showLoadMore?: boolean;
  title?: string;
  subtitle?: string;
  kicker?: string;
};

export default function NewsBlogListClient({
  initialPosts = [],
  pageSize = 6,
  placeholderImage = "/Perla II - 2.png",
  showLoadMore = true,
 title = "Latest Posts",
subtitle = "Up-to-date blog articles about our projects, regions, and digital sales experiences.",
kicker = "Blog & News",

}: Props) {
  const [visible, setVisible] = useState(pageSize);

  const sorted = useMemo(() => {
    const list = Array.isArray(initialPosts) ? initialPosts : [];
    return [...list].sort((a, b) => {
      const da = a?.date ? +new Date(a.date) : 0;
      const db = b?.date ? +new Date(b.date) : 0;
      return db - da;
    });
  }, [initialPosts]);

  const shown = sorted.slice(0, visible);
  const canLoadMore = showLoadMore && visible < sorted.length;

  // Carousel turns on when we have more than 3 posts
  const useCarousel = shown.length > 3;

  // Carousel state/refs (Framer Motion)
  const containerRef = useRef<HTMLDivElement | null>(null);
  const trackRef = useRef<HTMLUListElement | null>(null);
  const x = useMotionValue(0);
  const [slideW, setSlideW] = useState(0);
  const [visibleSlides, setVisibleSlides] = useState(1);
  const [maxIndex, setMaxIndex] = useState(0);
  const [index, setIndex] = useState(0);

  // Drag/click guard + global selection toggle
  const isDraggingRef = useRef(false);
  const prevUserSelect = useRef<string>("");
  const prevWebkitUserSelect = useRef<string>("");

  const disableGlobalSelect = useCallback(() => {
    prevUserSelect.current = document.body.style.userSelect;
    prevWebkitUserSelect.current = document.body.style.getPropertyValue("-webkit-user-select");
    document.body.style.userSelect = "none";
    document.body.style.setProperty("-webkit-user-select", "none");
  }, []);

  const enableGlobalSelect = useCallback(() => {
    document.body.style.userSelect = prevUserSelect.current || "";
    if (prevWebkitUserSelect.current) {
      document.body.style.setProperty("-webkit-user-select", prevWebkitUserSelect.current);
    } else {
      document.body.style.removeProperty("-webkit-user-select");
    }
  }, []);

  useEffect(() => {
    return () => {
      // safety on unmount
      enableGlobalSelect();
    };
  }, [enableGlobalSelect]);

  const step = slideW ? slideW + GAP_PX : 0;

  const recalc = useCallback(() => {
    const cont = containerRef.current;
    const track = trackRef.current;
    if (!cont || !track) return;

    const first = track.querySelector("li");
    if (!first) return;

    const rect = first.getBoundingClientRect();
    const w = rect.width;
    setSlideW(w);

    // include the gap in the visible-slides calculation
    const vis = Math.max(1, Math.floor((cont.clientWidth + GAP_PX) / (w + GAP_PX)));
    setVisibleSlides(vis);

    const max = Math.max(0, shown.length - vis);
    setMaxIndex(max);

    // Snap current index back into bounds on resize
    setIndex((prev) => {
      const clamped = Math.min(Math.max(prev, 0), max);
      const target = -clamped * (w + GAP_PX);
      x.set(target);
      return clamped;
    });
  }, [shown.length, x]);

  useEffect(() => {
    if (!useCarousel) return;
    recalc();
    const onResize = () => recalc();
    window.addEventListener("resize", onResize);
    return () => window.removeEventListener("resize", onResize);
  }, [useCarousel, recalc]);

  const goTo = useCallback(
    (i: number) => {
      const clamped = Math.min(Math.max(i, 0), maxIndex);
      setIndex(clamped);
      if (!step) return;
      const target = -clamped * step;
      animate(x, target, { type: "spring", stiffness: 260, damping: 30, mass: 0.8 });
    },
    [maxIndex, step, x]
  );

  const next = useCallback(() => goTo(index + 1), [goTo, index]);
  const prev = useCallback(() => goTo(index - 1), [goTo, index]);

  // Snap to nearest slide at the end of a drag
  const snapAfterDrag = useCallback(() => {
    if (!step) return;
    const currentX = x.get();
    const raw = -currentX / step;
    const nearest = Math.round(raw);
    goTo(nearest);
  }, [goTo, step, x]);

  // Handlers to guard against click after drag
  const handleDragStart = useCallback(() => {
    isDraggingRef.current = true;
    disableGlobalSelect(); // hard block selection across the page during drag
  }, [disableGlobalSelect]);

  const handleDragEnd = useCallback(() => {
    snapAfterDrag();
    // tiny delay to avoid immediate click after drag end
    setTimeout(() => {
      isDraggingRef.current = false;
      enableGlobalSelect();
    }, 50);
  }, [snapAfterDrag, enableGlobalSelect]);

  return (
    <section
      aria-label="News & Blog"
      className="relative overflow-hidden"
      style={{ background: "#ffffff", color: "#141517" }}
      data-bg="light"
    >
      <div className="relative mx-auto max-w-7xl px-4 sm:px-6 lg:px-8 py-16 lg:py-24">
        {/* top hairline */}
        <div className="pointer-events-none absolute inset-x-0 top-0 h-px bg-[rgba(20,21,23,0.08)]" />

        {/* subtle radial accents */}
        <div
          aria-hidden
          className="pointer-events-none absolute inset-0 -z-10"
          style={{
            background:
              "radial-gradient(60% 60% at 8% 12%, rgba(39,149,155,0.05), transparent 60%), radial-gradient(50% 50% at 90% 10%, rgba(241,92,52,0.05), transparent 60%)",
          }}
        />

        {/* Kicker chip */}
        <motion.span
          variants={item}
          initial="hidden"
          whileInView="show"
          viewport={{ once: false, amount: 0.35 }}
          className="inline-flex items-center text-[11px] tracking-wider uppercase px-3 py-1 rounded-full"
          style={{
            background: "rgba(255, 255, 255, 0.05)",
            border: "1px solid rgba(20,21,23,0.08)",
            color: TEAL,
          }}
        >
          {kicker}
        </motion.span>

        {/* Heading + sub */}
        <div className="mt-6">
          <motion.h2
            variants={item}
            initial="hidden"
            whileInView="show"
            viewport={{ once: false, amount: 0.35 }}
            className="text-3xl sm:text-4xl lg:text-5xl font-semibold leading-tight"
          >
            {title}
          </motion.h2>
          {subtitle && (
            <motion.p
              variants={item}
              initial="hidden"
              whileInView="show"
              viewport={{ once: false, amount: 0.35 }}
              className="mt-2 text-sm sm:text-base"
              style={{ color: "rgba(20,21,23,0.72)" }}
            >
              {subtitle}
            </motion.p>
          )}
        </div>

        {/* ---------- GRID (<= 3 posts) ---------- */}
        {!useCarousel && (
          <motion.ul
            variants={wrap}
            initial="hidden"
            whileInView="show"
            viewport={{ amount: 0.2, once: false }}
            className="mx-auto mt-10 md:mt-12 max-w-7xl grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6"
          >
            {shown.map((p, idx) => {
              const extras = loose(p);
              const img = p.cover || placeholderImage;
              const slug =
                p.slug ??
                (typeof extras.id === "string" || typeof extras.id === "number" ? String(extras.id) : "");
              const href = slug ? `/tr/blog/${slug}` : "/tr/blog";
              const date =
                p.date &&
                new Date(p.date).toLocaleDateString("tr-TR", {
                  year: "numeric",
                  month: "short",
                  day: "2-digit",
                });
              const readTime = typeof extras.readTime === "number" ? (extras.readTime as number) : undefined;
              const author = typeof extras.author === "string" ? (extras.author as string) : undefined;

              return (
                <motion.li key={slug || `post-${idx}`} variants={item} className="h-full">
                  <Link
                    href={href}
                    draggable={false}
                    onDragStart={(e) => e.preventDefault()}
                    className="group h-full flex flex-col overflow-hidden rounded-2xl border border-black/10 bg-white/70 backdrop-blur-xl shadow transition hover:shadow-lg select-none [-webkit-user-drag:none]"
                  >
                    {/* Thumb */}
                    <div className="relative aspect-[16/10] shrink-0">
                      {img ? (
                        <Image
                          src={img}
                          alt={p.title || "Article image"}
                          fill
                          draggable={false}
                          className="object-cover transition-transform duration-500 group-hover:scale-[1.03] pointer-events-none"
                          unoptimized={isHttpUrl(img)}
                          sizes="(max-width: 640px) 100vw, (max-width: 1024px) 50vw, 33vw"
                        />
                      ) : (
                        <div className="absolute inset-0 grid place-items-center text-xs text-black/40">
                          No cover
                        </div>
                      )}
                    </div>

                    {/* Body */}
                    <div className="flex-1 p-4 flex flex-col select-none">
                      <div className="text-xs text-black/60">
                        {date}
                        {typeof readTime === "number" ? ` • ${readTime} dk` : ""}
                        {author ? ` • ${author}` : ""}
                      </div>
                      <h3 className="mt-2 text-lg font-semibold line-clamp-2 min-h-[3.2rem]">
                        {p.title}
                      </h3>
                      {p.excerpt ? (
                        <p className="mt-1 text-sm text-black/70 line-clamp-2">{p.excerpt}</p>
                      ) : null}
                    </div>
                  </Link>
                </motion.li>
              );
            })}
          </motion.ul>
        )}

        {/* ---------- CAROUSEL (> 3 posts) ---------- */}
        {useCarousel && (
          <div className="relative mt-10 md:mt-12 overflow-hidden" ref={containerRef}>
            {/* Track */}
            <motion.ul
              ref={trackRef}
              className="flex items-stretch gap-6 select-none cursor-grab active:cursor-grabbing"
              drag="x"
              dragConstraints={{ left: -(maxIndex * (step || 0)), right: 0 }}
              dragElastic={0.05}
              onDragStart={handleDragStart}
              onDragEnd={handleDragEnd}
              style={{
                x,
                touchAction: "pan-y",
                userSelect: "none",
              }}
            >
              {shown.map((p, idx) => {
                const extras = loose(p);
                const img = p.cover || placeholderImage;
                const slug =
                  p.slug ??
                  (typeof extras.id === "string" || typeof extras.id === "number" ? String(extras.id) : "");
                const href = slug ? `/tr/blog/${slug}` : "/tr/blog";
                const date =
                  p.date &&
                  new Date(p.date).toLocaleDateString("tr-TR", {
                    year: "numeric",
                    month: "short",
                    day: "2-digit",
                  });
                const readTime = typeof extras.readTime === "number" ? (extras.readTime as number) : undefined;
                const author = typeof extras.author === "string" ? (extras.author as string) : undefined;

                return (
                  <li
                    key={slug || `post-${idx}`}
                    className="
                      shrink-0
                      w-[85vw] sm:w-[70vw] md:w-[55vw]
                      lg:basis-[calc((100%_-_48px)/3)] lg:w-auto
                      max-w-none
                    "
                  >
                    <Link
                      href={href}
                      draggable={false}
                      onDragStart={(e) => e.preventDefault()} // stop native link drag
                      onClick={(e) => {
                        if (isDraggingRef.current) {
                          e.preventDefault();
                          e.stopPropagation();
                        }
                      }}
                      className="group h-full flex flex-col overflow-hidden rounded-2xl border border-black/10 bg-white/70 backdrop-blur-xl shadow transition hover:shadow-lg select-none [-webkit-user-drag:none]"
                    >
                      {/* Thumb */}
                      <div className="relative aspect-[16/10] shrink-0">
                        {img ? (
                          <Image
                            src={img}
                            alt={p.title || "Article image"}
                            fill
                            draggable={false}
                            className="object-cover transition-transform duration-500 group-hover:scale-[1.03] pointer-events-none"
                            unoptimized={isHttpUrl(img)}
                            sizes="(max-width: 640px) 85vw, (max-width: 1024px) 70vw, (max-width:1280px) 55vw, 33vw"
                          />
                        ) : (
                          <div className="absolute inset-0 grid place-items-center text-xs text-black/40">
                            No cover
                          </div>
                        )}
                      </div>

                      {/* Body */}
                      <div className="flex-1 p-4 flex flex-col select-none">
                        <div className="text-xs text-black/60">
                          {date}
                          {typeof readTime === "number" ? ` • ${readTime} dk` : ""}
                          {author ? ` • ${author}` : ""}
                        </div>
                        <h3 className="mt-2 text-lg font-semibold line-clamp-2 min-h-[3.2rem]">
                          {p.title}
                        </h3>
                        {p.excerpt ? (
                          <p className="mt-1 text-sm text-black/70 line-clamp-2">{p.excerpt}</p>
                        ) : null}
                      </div>
                    </Link>
                  </li>
                );
              })}
            </motion.ul>

            {/* Arrows */}
            <div className="pointer-events-none absolute inset-y-0 left-0 right-0 z-20 flex items-center justify-between px-2">
              <button
                onClick={prev}
                disabled={index <= 0}
                className="pointer-events-auto rounded-full border border-black/10 bg-white/70 backdrop-blur px-3 py-2 shadow disabled:opacity-40"
                aria-label="Previous"
                style={{ color: "rgba(20,21,23,0.85)" }}
              >
                ←
              </button>
              <button
                onClick={next}
                disabled={index >= maxIndex}
                className="pointer-events-auto rounded-full border border-black/10 bg-white/70 backdrop-blur px-3 py-2 shadow disabled:opacity-40"
                aria-label="Next"
                style={{ color: "rgba(20,21,23,0.85)" }}
              >
                →
              </button>
            </div>

            {/* Dots */}
            <div className="mt-6 flex justify-center gap-2 z-10 relative">
              {Array.from({ length: maxIndex + 1 }).map((_, i) => (
                <button
                  key={i}
                  onClick={() => goTo(i)}
                  aria-label={`Page ${i + 1}`}
                  className="h-2 w-2 rounded-full transition"
                  style={{
                    background: i === index ? ORANGE : "rgba(20,21,23,0.18)",
                    transform: i === index ? "scale(1.15)" : "scale(1)",
                  }}
                />
              ))}
            </div>
          </div>
        )}

        {/* Load more (only when not using carousel) */}
        {!useCarousel && canLoadMore && (
          <div className="mt-12 md:mt-14 flex justify-center gap-3">
            <button
              onClick={() => setVisible((v) => v + pageSize)}
              className="rounded-full px-7 py-2.5 text-sm font-medium transition-transform hover:-translate-y-0.5"
              style={{ background: `${ORANGE}14`, color: ORANGE, border: `1px solid ${ORANGE}33` }}
            >
              Daha Fazla Yükle
            </button>
            <Link
              href="/tr/blog"
              className="rounded-full px-7 py-2.5 text-sm font-medium transition-transform hover:-translate-y-0.5"
              style={{
                background: "rgba(20,21,23,0.06)",
                border: "1px solid rgba(20,21,23,0.12)",
                color: "rgba(20,21,23,0.85)",
              }}
            >
              All Articles
            </Link>
          </div>
        )}
      </div>
    </section>
  );
}

// app/components/ProjectVideoSlider.tsx
"use client";

import React, { useCallback, useEffect, useMemo, useRef, useState } from "react";
import Link from "next/link";
import { m as motion, useReducedMotion, type Variants } from "framer-motion";
import { Volume2, VolumeX, Maximize2, Minimize2, ChevronLeft, ChevronRight } from "lucide-react";

// Swiper
import { Swiper, SwiperSlide } from "swiper/react";
import { Autoplay, Pagination, EffectFade, Keyboard } from "swiper/modules";
import type { Swiper as SwiperType } from "swiper/types";

const TEAL = "#27959b";
const ORANGE = "#f15c34";

/* ---------------- Motion ---------------- */
const fadeUp: Variants = {
  hidden: { opacity: 0, y: 18 },
  show: {
    opacity: 1,
    y: 0,
    transition: { duration: 0.55, ease: [0.22, 1, 0.36, 1] as const },
  },
};
const containerStagger: Variants = {
  hidden: {},
  show: { transition: { staggerChildren: 0.06, delayChildren: 0.1 } },
};

/* ---------------- Utils ---------------- */
const extractYouTubeId = (url: string) => {
  try {
    const u = new URL(url);
    if (u.hostname.includes("youtube.com")) return u.searchParams.get("v") || "";
    if (u.hostname.includes("youtu.be")) return u.pathname.replace("/", "");
  } catch {}
  return url;
};
const ytThumb = (id: string) => `https://img.youtube.com/vi/${id}/hqdefault.jpg`;
const toMinSec = (secs?: number) => {
  if (secs === undefined || !Number.isFinite(secs)) return "–:–";
  const m = Math.floor(secs / 60);
  const s = Math.floor(secs % 60);
  return `${m}:${s.toString().padStart(2, "0")}`;
};

/* ---------------- Types ---------------- */
// Basit, yerel YouTube Iframe API tipleri (paket eklemeden çalışır)
type YTVideoData = { author?: string };
interface YTPlayer {
  playVideo(): void;
  pauseVideo(): void;
  seekTo(seconds: number, allowSeekAhead: boolean): void;
  mute(): void;
  unMute(): void;
  destroy(): void;
  getDuration(): number;
  getVideoData(): YTVideoData;
}
type YTReadyEvent = { target: YTPlayer };
type YTPlayerOptions = {
  videoId: string;
  width?: string | number;
  height?: string | number;
  playerVars?: Record<string, unknown>;
  events?: { onReady?: (ev: YTReadyEvent) => void };
};
interface YTGlobal {
  Player: new (elementId: string | HTMLElement, options: YTPlayerOptions) => YTPlayer;
}
interface WindowWithYT extends Window {
  YT?: YTGlobal;
  onYouTubeIframeAPIReady?: () => void;
}

// CSS değişkenlerini güvenle verebilmek için yardımcı tip
type CSSVars = React.CSSProperties & { [key: `--${string}`]: string | number };

type CTALink = { label: string; href: string };
type SlideContent = {
  customHeadline: string;
  tagline?: string;
  bullets?: string[];
  primaryCta?: CTALink | null;
  secondaryCta?: CTALink | null;
};
type SlideInput = {
  id: number;
  videoUrl: string;
  backgroundImage?: string;
  badge?: string;
  content: SlideContent;
};

export type ProjectVideoSliderProps = {
  slides?: SlideInput[];
  autoplayMs?: number; // default 10000
  className?: string;
};

/* ---------------- YouTube API Loader ---------------- */
let ytApiPromise: Promise<YTGlobal | null> | null = null;

function ensureYouTubeAPI(): Promise<YTGlobal | null> {
  if (typeof window === "undefined") return Promise.resolve(null);
  const w = window as WindowWithYT;
  if (w.YT && w.YT.Player) return Promise.resolve(w.YT);

  if (!ytApiPromise) {
    ytApiPromise = new Promise<YTGlobal | null>((resolve) => {
      const existing = document.getElementById("youtube-iframe-api");
      if (!existing) {
        const tag = document.createElement("script");
        tag.id = "youtube-iframe-api";
        tag.src = "https://www.youtube.com/iframe_api";
        document.body.appendChild(tag);
      }
      w.onYouTubeIframeAPIReady = () => resolve((window as WindowWithYT).YT ?? null);
      const deadline = Date.now() + 10000;
      const check = () => {
        const ww = window as WindowWithYT;
        if (ww.YT && ww.YT.Player) resolve(ww.YT);
        else if (Date.now() < deadline) setTimeout(check, 120);
        else resolve(null);
      };
      check();
    });
  }
  return ytApiPromise;
}

/* ---------------- Main Component ---------------- */
export default function   ProjectVideoSlider({
  autoplayMs = 10000,
  className = "",
  slides = DEFAULT_SLIDES,
}: ProjectVideoSliderProps) {
  const playersRef = useRef<(YTPlayer | null)[]>([]);
  const swiperRef = useRef<SwiperType | null>(null);
  const [autoplayStopped, setAutoplayStopped] = useState(false);
  const [activeSlide, setActiveSlide] = useState(0);
  const reducedMotion = useReducedMotion();

  const registerPlayer = useCallback((index: number, player: YTPlayer | null) => {
    playersRef.current[index] = player;
  }, []);

  const playOnly = useCallback((activeIndex: number) => {
    playersRef.current.forEach((p, i) => {
      if (!p) return;
      try {
        if (i === activeIndex && !reducedMotion) {
          p.playVideo?.();
        } else {
          p.pauseVideo?.();
          p.seekTo?.(0, true);
        }
      } catch {}
    });
  }, [reducedMotion]);

  const stopAutoplay = useCallback(() => {
    if (autoplayStopped) return;
    try {
      swiperRef.current?.autoplay?.stop();
      setAutoplayStopped(true);
    } catch {}
  }, [autoplayStopped]);

  const paginationVars: CSSVars = {
    "--swiper-pagination-color": "#ffffff",
    "--swiper-pagination-bullet-inactive-color": "rgba(255,255,255,0.5)",
    "--swiper-pagination-bullet-inactive-opacity": 1,
  };

  return (
    <section
      aria-label="Project video carousel"
      className={`relative w-full overflow-hidden bg-black ${className}`}
      style={{ color: "#fff" }}
      data-bg="dark"
    >
      {/* Custom white nav arrows */}
      <button
        type="button"
        aria-label="Previous slide"
        onClick={() => swiperRef.current?.slidePrev()}
        className="absolute z-20 left-2 md:left-4 bottom-1 -translate-y-1/2 rounded-full p-2 md:p-3 bg-white/10 hover:bg-white/20 border border-white/30 shadow-lg backdrop-blur-md"
      >
        <ChevronLeft size={22} />
      </button>
      <button
        type="button"
        aria-label="Next slide"
        onClick={() => swiperRef.current?.slideNext()}
        className="absolute z-20 right-2 md:right-4 bottom-1 -translate-y-1/2 rounded-full p-2 md:p-3 bg-white/10 hover:bg-white/20 border border-white/30 shadow-lg backdrop-blur-md"
      >
        <ChevronRight size={22} />
      </button>

      <Swiper
        modules={[Autoplay, Pagination, EffectFade, Keyboard]}
        slidesPerView={1}
        effect="fade"
        fadeEffect={{ crossFade: true }}
        loop
        autoHeight
        autoplay={
          autoplayStopped || reducedMotion
            ? false
            : {
                delay: autoplayMs,
                disableOnInteraction: false, // unmute/fullscreen manuel durduruyor
                pauseOnMouseEnter: false,
              }
        }
        pagination={{ clickable: true }}
        keyboard={{ enabled: true, onlyInViewport: true }}
        noSwiping
        noSwipingClass="swiper-no-swiping"
        onSwiper={(swiper) => {
          swiperRef.current = swiper;
          playOnly(swiper.realIndex);
        }}
        onSlideChange={(swiper) => { setActiveSlide(swiper.realIndex); playOnly(swiper.realIndex); }}
        className="relative"
        style={paginationVars}
      >
        {slides.map((s, idx) => {
          const vid = extractYouTubeId(s.videoUrl);
          const bg = s.backgroundImage || ytThumb(vid);
          return (
            <SwiperSlide key={s.id}>
              <SlideContentBlock
                active={idx === activeSlide}
                index={idx}
                id={vid}
                bgImage={bg}
                badge={s.badge ?? "Video"}
                content={s.content}
                onPlayerReady={(player) => registerPlayer(idx, player)}
                onNeedStopAutoplay={stopAutoplay}
              />
            </SwiperSlide>
          );
        })}
      </Swiper>
    </section>
  );
}

/* ---------------- Slide ---------------- */
function SlideContentBlock({
  active,
  index,
  id,
  bgImage,
  badge,
  content,
  onPlayerReady,
  onNeedStopAutoplay,
}: {
  active: boolean;
  index: number;
  id: string;
  bgImage: string;
  badge: string;
  content: SlideContent;
  onPlayerReady: (player: YTPlayer | null) => void;
  onNeedStopAutoplay: () => void;
}) {
  const [author, setAuthor] = useState<string>("");
  const [duration, setDuration] = useState<string>("–:–");

  const handleMeta = useCallback((p: YTPlayer) => {
    try {
      const data = p.getVideoData?.() || {};
      setAuthor(data.author || "");
      const d = p.getDuration?.();
      if (typeof d === "number" && d > 0) setDuration(toMinSec(d));
    } catch {}
  }, []);

  return (
    <div className="relative min-h-[560px] md:min-h-[640px]">
      {/* Background */}
      <div aria-hidden className="absolute inset-0 bg-cover bg-center" style={{ backgroundImage: `url(${bgImage})` }} />
      {/* Readability + subtle vignette */}
      <div aria-hidden className="absolute inset-0 bg-gradient-to-br from-black/70 via-black/55 to-black/60" />
      <div aria-hidden className="pointer-events-none absolute inset-0 [box-shadow:inset_0_0_150px_rgba(0,0,0,.45)]" />

      {/* Content */}
      <div className="relative mx-auto max-w-7xl px-4 sm:px-6 lg:px-8 pt-14 lg:pt-20 pb-12 lg:pb-20">
        <motion.div
          variants={containerStagger}
          initial="hidden"
          whileInView="show"
          viewport={{ once: false, amount: 0.25 }}
          className="grid lg:grid-cols-12 gap-10 items-center"
        >
          {/* Left */}
          <motion.div variants={fadeUp} className="lg:col-span-6">
            <span
              className="inline-block text-[12px] uppercase tracking-wide px-3 py-1 rounded-full mb-3 backdrop-blur-md"
              style={{ background: `${TEAL}44`, color: "#fff", border: `1px solid ${TEAL}66` }}
            >
              {badge}
            </span>

            <h2 className="text-3xl sm:text-4xl lg:text-5xl font-semibold leading-tight drop-shadow-lg">
              {content.customHeadline}
            </h2>

            {content.tagline && (
              <p className="mt-3 text-white/85 text-base sm:text-lg max-w-[60ch] drop-shadow">
                {content.tagline}
              </p>
            )}

            {(author || duration) && (
              <div className="mt-5 grid grid-cols-2 gap-3 max-w-md">
                <StatPill label="Duration" value={duration} />
                <StatPill label="Source" value={author || "YouTube"} />
              </div>
            )}

            {!!content.bullets?.length && (
              <ul className="mt-6 space-y-2">
                {content.bullets.slice(0, 4).map((b, i) => (
                  <li key={i} className="flex items-start gap-2">
                    <span
                      className="mt-[6px] inline-block h-[10px] w-[10px] rounded-full"
                      style={{ background: ORANGE, boxShadow: `0 0 0 3px ${ORANGE}33` }}
                    />
                    <p className="text-white/90">{b}</p>
                  </li>
                ))}
              </ul>
            )}

            <div className="mt-7 flex flex-wrap gap-4">
              {content.primaryCta !== null && content.primaryCta && (
                <Link
                  href={content.primaryCta.href}
                  className="px-6 py-2.5 rounded-full text-sm font-medium transition-transform hover:-translate-y-0.5 backdrop-blur-md"
                  style={{ background: TEAL, color: "#fff", boxShadow: `0 10px 24px ${TEAL}55` }}
                >
                  {content.primaryCta.label}
                </Link>
              )}
              {content.secondaryCta !== null && content.secondaryCta && (
                <Link
                  href={content.secondaryCta.href}
                  className="px-6 py-2.5 rounded-full text-sm font-medium backdrop-blur-md"
                  style={{ background: `${ORANGE}33`, color: "#fff", border: `1px solid ${ORANGE}66` }}
                >
                  {content.secondaryCta.label}
                </Link>
              )}
            </div>
          </motion.div>

          {/* Right: video */}
          <motion.div variants={fadeUp} className="lg:col-span-6">
         {active ? <YouTubePanel
  videoId={id}
  index={index}
  onReady={(player) => {
    onPlayerReady(player);
    if (player) handleMeta(player); // <<< null guard
  }}
  onNeedStopAutoplay={onNeedStopAutoplay}
/> : <div className="aspect-video overflow-hidden rounded-2xl bg-black"><img src={ytThumb(id)} alt={content.customHeadline} loading="lazy" decoding="async" className="h-full w-full object-cover" /></div>}
          </motion.div>
        </motion.div>
      </div>
    </div>
  );
}

/* ---------------- Video Panel ---------------- */
function YouTubePanel({
  videoId,
  index,
  onReady,
  onNeedStopAutoplay,
}: {
  videoId: string;
  index: number;
  onReady: (player: YTPlayer | null) => void;
  onNeedStopAutoplay: () => void;
}) {
  const containerId = useMemo(() => `yt-player-${index}-${videoId}`, [index, videoId]);
  const [muted, setMuted] = useState(true);
  const [isFullscreen, setIsFullscreen] = useState(false);
  const playerRef = useRef<YTPlayer | null>(null);
  const panelRef = useRef<HTMLDivElement | null>(null);
  const reducedMotion = useReducedMotion();
  const readyCallback = useRef(onReady);
  useEffect(() => { readyCallback.current = onReady; }, [onReady]);

  // Watch fullscreen changes to update UI and stop autoplay
  useEffect(() => {
    const onFsChange = () => {
      const active = !!document.fullscreenElement && !!panelRef.current?.contains(document.fullscreenElement);
      setIsFullscreen(active);
      if (active) onNeedStopAutoplay();
    };
    document.addEventListener("fullscreenchange", onFsChange);
    return () => document.removeEventListener("fullscreenchange", onFsChange);
  }, [onNeedStopAutoplay]);

useEffect(() => {
  let mounted = true;

  ensureYouTubeAPI().then((YT) => {
    if (!mounted || !YT) return;
    const loopParams: { loop: 1; playlist: string } = { loop: 1, playlist: videoId };
    const player = new YT.Player(containerId, {
      videoId,
      width: "100%",
      height: "100%",
      playerVars: {
        autoplay: reducedMotion ? 0 : 1,
        mute: 1,
        controls: 0,
        rel: 0,
        playsinline: 1,
        modestbranding: 1,
        iv_load_policy: 3,
        ...loopParams,
      },
      events: {
        onReady: (ev) => {
          if (!mounted) { ev.target.destroy(); return; }
          playerRef.current = ev.target;
          try {
            ev.target.mute();
            if (!reducedMotion) ev.target.playVideo();
          } catch {}
          readyCallback.current(ev.target);
        },
      },
    });
    playerRef.current = player;
  });

  return () => {
    mounted = false; // <<< önemli: prefer-const uyarısını da çözer
    try {
      playerRef.current?.destroy?.();
      playerRef.current = null;
      readyCallback.current(null);
    } catch {}
  };
}, [containerId, videoId, reducedMotion]);


  const toggleMute = useCallback(() => {
    const p = playerRef.current;
    if (!p) return;
    try {
      if (muted) {
        p.unMute?.();
        p.playVideo?.();
        onNeedStopAutoplay(); // unmute -> slider autoplay durur
      } else {
        p.mute?.();
      }
      setMuted((m) => !m);
    } catch {}
  }, [muted, onNeedStopAutoplay]);

  const toggleFullscreen = useCallback(async () => {
    try {
      if (!document.fullscreenElement) {
        await panelRef.current?.requestFullscreen?.();
      } else {
        await document.exitFullscreen();
      }
      onNeedStopAutoplay();
    } catch {}
  }, [onNeedStopAutoplay]);

  return (
    <div
      ref={panelRef}
      className="relative rounded-2xl overflow-hidden border bg-white/5 backdrop-blur-md shadow-[0_6px_24px_rgba(0,0,0,.45)] swiper-no-swiping"
      style={{ borderColor: "rgba(255,255,255,0.15)" }}
    >
      <div className="aspect-video w-full swiper-no-swiping">
        <div id={containerId} className="h-full w-full" />
      </div>

      {/* Bottom-left: Mute/Unmute */}
      <button
        type="button"
        onClick={(e) => {
          e.preventDefault();
          e.stopPropagation();
          toggleMute();
        }}
        aria-pressed={!muted}
        className="absolute bottom-3 left-3 inline-flex items-center gap-2 rounded-full px-3 py-2 text-sm font-medium shadow-lg backdrop-blur-md swiper-no-swiping"
        style={{
          background: muted ? `${ORANGE}1A` : `${TEAL}1A`,
          color: "#fff",
          border: `1px solid ${muted ? `${ORANGE}66` : `${TEAL}66`}`,
        }}
        title={muted ? "Unmute" : "Mute"}
      >
        {muted ? <VolumeX size={16} /> : <Volume2 size={16} />}
        {muted ? "Unmute" : "Mute"}
      </button>

      {/* Bottom-right: Fullscreen */}
      <button
        type="button"
        onClick={(e) => {
          e.preventDefault();
          e.stopPropagation();
          toggleFullscreen();
        }}
        aria-pressed={isFullscreen}
        className="absolute bottom-3 right-3 inline-flex items-center gap-2 rounded-full px-3 py-2 text-sm font-medium shadow-lg backdrop-blur-md swiper-no-swiping"
        style={{
          background: `rgba(0,0,0,.25)`,
          color: "#fff",
          border: `1px solid rgba(255,255,255,.35)`,
        }}
        title={isFullscreen ? "Exit fullscreen" : "Fullscreen"}
      >
        {isFullscreen ? <Minimize2 size={16} /> : <Maximize2 size={16} />}
        {isFullscreen ? "Exit" : "Fullscreen"}
      </button>
    </div>
  );
}

/* ---------------- Small UI ---------------- */
function StatPill({ label, value }: { label: string; value: string }) {
  return (
    <div
      className="rounded-xl p-3 bg-white/10 backdrop-blur-md border shadow-[0_6px_20px_rgba(0,0,0,.4)]"
      style={{ borderColor: "rgba(255,255,255,0.15)" }}
    >
      <div className="text-[11px] uppercase tracking-wide text-white/70">{label}</div>
      <div className="text-lg sm:text-xl font-semibold text-white">{value}</div>
    </div>
  );
}

