"use client";

import Image from "@/app/components/performance/DeferredFillImage";
import React, { useMemo, useState } from "react";
import { m as motion, type Variants, type Easing } from "framer-motion";

const TEAL = "#27959b";
const ORANGE = "#f15c34";
const EASE: Easing = [0.22, 1, 0.36, 1] as const;

const fadeUp: Variants = {
  hidden: { opacity: 0, y: 16 },
  show: {
    opacity: 1,
    y: 0,
    transition: { duration: 0.45, ease: EASE },
  },
};

type GalleryItem = {
  src: string;   // public/ yolundan görsel
  alt?: string;
  label?: string; // (opsiyonel) alt cam şerit etiketi
};

export default function MariachiGalleryExpanding({
  title = "La Joya Gallery",
subtitle = "La Joya Images",

  items,
}: {
  title?: string;
  subtitle?: string;
  items?: GalleryItem[];
}) {
  // 5 görsel için örnek veri — kendi yollarınızla değiştirin
  const data: GalleryItem[] = useMemo(
    () =>
      items ?? [
        { src: "/la-joya/1.jpg", alt: "La Joya project image 1" },
        { src: "/la-joya/2.jpg", alt: "La Joya project image 2" },
        { src: "/la-joya/3.jpg", alt: "La Joya project image 3" },
        { src: "/la-joya/6.jpg", alt: "La Joya project image 4" },
        { src: "/la-joya/5.jpg", alt: "La Joya project image 5" },


      ],
    [items]
  );

  // Hover / Tap aktif panel
  const [hovered, setHovered] = useState<number | null>(null);
  const [active, setActive] = useState<number | null>(null);

  // Kart için büyüme oranı
  const growth = (i: number) => {
    // Tap ile seçilmişse onu esas al
    if (active !== null) return i === active ? 3.2 : 0.8;
    // Hover varsa ona göre
    if (hovered !== null) return i === hovered ? 3.2 : 0.8;
    // Varsayılan
    return 1;
  };

  return (
    <section
