                  allowFullScreen
                />
              ) : videoSrc ? (
                <video
                  className="absolute inset-0 h-full w-full object-cover"
                  // 🔽 Autoplay-friendly attributes
                  autoPlay
                  muted
                  playsInline
                  loop
                  controls
                  poster={poster}
