}

/* -------- Small chip helper -------- */
function Chip({
  text,
  color,
  neutral = false,
}: {
  text: string;
  color: string;
  neutral?: boolean;
}) {
  const styles = neutral
    ? {
        background: "rgba(255,255,255,0.15)",
        border: "1px solid rgba(255,255,255,0.28)",
        color: "#fff",
      }
    : {
        background: `${color}33`,
        border: `1px solid ${color}66`,
        color: "#fff",
      };

  return (
    <span
      className="text-xs px-3 py-1 rounded-full"
      style={styles as React.CSSProperties}
    >
      {text}
    </span>
  );
}

