function useNormalizedPathname() {
  const raw = usePathname() || "/";
  const noHash = raw.split("#")[0].split("?")[0];
  const noLocale = noHash.replace(/^\/(tr|en)(?=\/|$)/i, "");
  const clean = noLocale.replace(/\/+$/, "") || "/";
  return clean;
}




// current locale from URL
function useLocale() {
  const raw = usePathname() || "/";
  return /^\/en(\/|$)/i.test(raw) ? "en" : "tr";
}

// build a locale-prefixed path from a clean path (no locale)
function withLocale(locale: "tr" | "en", cleanPath: string) {
  return locale === "tr"
    ? `/tr${cleanPath === "/" ? "" : cleanPath}`
    : `/en${cleanPath === "/" ? "" : cleanPath}`;
}




