// app/components/mariachi/MariachiGalleryExpanding.tsx
"use client";

import React, { useMemo, useState } from "react";
import Image from "@/app/components/performance/DeferredFillImage";
import { m as motion, type Variants, type Easing } from "framer-motion";

const TEAL = "#27959b";
const ORANGE = "#f15c34";
const EASE: Easing = [0.22, 1, 0.36, 1] as const;

const fadeUp: Variants = {
  hidden: { opacity: 0, y: 16 },
  show: {
    opacity: 1,
    y: 0,
    transition: { duration: 0.45, ease: EASE },
  },
};

type GalleryItem = {
  src: string;   // public/ yolundan görsel
  alt?: string;
  label?: string; // (opsiyonel) alt cam şerit etiketi
};

export default function MariachiGalleryExpanding({
  title = "Galeri",
  subtitle = "Lagoon Verde Görselleri",
  items,
}: {
  title?: string;
  subtitle?: string;
  items?: GalleryItem[];
}) {
  // 5 görsel için örnek veri — kendi yollarınızla değiştirin
  const data: GalleryItem[] = useMemo(
    () =>
      items ?? [
        { src: "/lagoon-verde/1.jpg", alt: "Lagoon Verde proje görseli 1" },
        { src: "/lagoon-verde/2.jpg", alt: "Lagoon Verde proje görseli 2" },
        { src: "/lagoon-verde/3.jpg", alt: "Lagoon Verde proje görseli 3" },
        { src: "/lagoon-verde/6.jpg", alt: "Lagoon Verde proje görseli 4" },
        { src: "/lagoon-verde/5.jpg", alt: "Lagoon Verde proje görseli 5" },
      ],
    [items]
  );

  // Hover / Tap aktif panel
  const [hovered, setHovered] = useState<number | null>(null);
  const [active, setActive] = useState<number | null>(null);

  // Kart için büyüme oranı
  const growth = (i: number) => {
    // Tap ile seçilmişse onu esas al
    if (active !== null) return i === active ? 3.2 : 0.8;
    // Hover varsa ona göre
    if (hovered !== null) return i === hovered ? 3.2 : 0.8;
    // Varsayılan
    return 1;
  };

  return (
    <section
      aria-label="Lagoon Verde — Galeri"
      className="relative overflow-hidden"
      style={{ background: "#ffffff", color: "#141517" }}
      data-bg="light"
    >
      {/* Sayfa arka plan dekoru — gradyanlı aura (cam hissi) */}
      <div
        aria-hidden
        className="pointer-events-none absolute -top-28 left-1/2 -translate-x-1/2 h-[28rem] w-[28rem] rounded-full blur-3xl opacity-30"
        style={{
          background:
            "radial-gradient(60% 60% at 50% 50%, rgba(39,149,155,0.22), transparent 70%)",
        }}
      />
      <div
        aria-hidden
        className="pointer-events-none absolute -bottom-24 right-1/4 h-[26rem] w-[26rem] rounded-full blur-3xl opacity-30"
        style={{
          background:
            "radial-gradient(60% 60% at 50% 50%, rgba(241,92,52,0.16), transparent 70%)",
        }}
      />

      {/* Başlık */}
      <div className="relative mx-auto max-w-7xl px-4 sm:px-6 lg:px-8 pt-12 lg:pt-16">
        <motion.div
          variants={fadeUp}
          initial="hidden"
          whileInView="show"
          viewport={{ once: false, amount: 0.35 }}
          className="max-w-3xl"
        >
          <h2 className="text-3xl sm:text-4xl lg:text-5xl font-semibold leading-tight">
            {title}
          </h2>
          <p className="mt-3 text-base sm:text-lg" style={{ color: "#141517CC" }}>
            {subtitle}
          </p>
        </motion.div>
      </div>

      {/* ==== FULL-WIDTH (full-bleed) GALERİ ==== */}
      <div
        className="relative w-screen left-1/2 -translate-x-1/2 mt-8"
        // not: bu "full-bleed" hilesi, sayfa container'ından taşarak tam ekran genişlik verir
      >
        <div
          className="group relative mx-auto"
          onMouseLeave={() => setHovered(null)}
          style={{ maxWidth: "100vw" }}
        >
          {/* Track */}
          <div
            className="flex items-stretch"
            style={{
              height: "60svh",
            }}
          >
            {data.map((g, i) => {
              const grow = growth(i);
              return (
                <div
                  key={g.src + i}
                  className="relative basis-0 min-w-0 overflow-hidden"
                  onMouseEnter={() => setHovered(i)}
                  onClick={() => setActive(active === i ? null : i)} // mobil için: dokununca sabitle
                  role="button"
                  aria-label={g.alt || `Galeri görseli ${i + 1}`}
                  style={{
                    flexGrow: grow,
                    transition: "flex-grow .55s cubic-bezier(0.22,1,0.36,1)",
                    cursor: "pointer",
                  }}
                >
                  {/* Görsel */}
                  {/* next/image + lazy: ham JPG preload (Link başlığı) oluşmaz */}
                  <Image
                    src={g.src}
                    alt={g.alt || ""}
                    fill
                    // Dar/uzun panelde object-cover için yükseklik de belirleyici
                    sizes="(max-width: 767px) 120vw, 60vw"
                    className="object-cover select-none"
                    draggable={false}
                    style={{
                      transform: grow > 1 ? "scale(1.06)" : "scale(1.02)",
                      transition: "transform .6s cubic-bezier(0.22,1,0.36,1)",
                    }}
                  />

                  {/* Üst cam parıltı */}
                  <div
                    aria-hidden
                    className="pointer-events-none absolute inset-0"
                    style={{
                      background:
                        grow > 1
                          ? "radial-gradient(60% 50% at 50% 0%, rgba(39,149,155,0.22), transparent 60%)"
                          : "radial-gradient(60% 40% at 50% 0%, rgba(255,255,255,0.08), transparent 60%)",
                      transition: "opacity .45s ease",
                    }}
                  />

                  {/* Alt cam şerit (etiket) */}
                  {g.label ? (
                    <div
                      className="absolute left-4 right-4 bottom-4 rounded-2xl px-4 py-2 backdrop-blur-md"
                      style={{
                        background:
                          "linear-gradient(180deg, rgba(255,255,255,0.16), rgba(255,255,255,0.10))",
                        border: "1px solid rgba(255,255,255,0.26)",
                        color: "#fff",
                        boxShadow: "0 10px 24px rgba(0,0,0,0.25)",
                      }}
                    >
                      <div className="text-sm font-medium drop-shadow">{g.label}</div>
                    </div>
                  ) : null}
                </div>
              );
            })}
          </div>
        </div>
      </div>

      {/* Küçük ipucu */}
      <div className="relative mx-auto max-w-7xl px-4 sm:px-6 lg:px-8 pb-10 lg:pb-14">
        <p className="mt-5 text-xs" style={{ color: "#14151799" }}>
          *Mobilde bir görsele dokunarak büyütüp sabitleyebilir, tekrar dokunarak varsayılan görünüme dönebilirsiniz.
        </p>
      </div>
    </section>
  );
}

// app/components/projects/Perla2Hero.tsx
import React from "react";
import Image from "next/image";
import type { Variants } from "framer-motion";

const TEAL = "#27959b";
const ORANGE = "#f15c34";

// Hero metinleri JS gecikse de görünür kalsın: opaklık 0'dan başlamaz, yalnızca hafif y kayması
const fadeUp: Variants = {
  hidden: { y: 14 },
  show: (i: number = 0) => ({
    y: 0,
    transition: { duration: 0.55, delay: i * 0.06, ease: [0.22, 1, 0.36, 1] },
  }),
};

type Props = {
  title?: string;
  tagline?: string;
  location?: string;
  statusTR?: string;
  delivery?: string;
  heroImage?: string;   // background image
  heroAlt?: string;
  /** .pdf ise yeni sekmede açılır; "#catalog" gibi bir çapa ise sayfada kaydırır */
  brochureHref?: string;
  brochureLabel?: string;
  contactHref?: string;
  contactLabel?: string;
  kicker?: string;
  /** Optional: override top-scrim height (px) if your header is taller/shorter */
  topScrimHeight?: number;
};

export default function Perla2Hero({
  title = "Lagoon Verde",
  tagline = "Bahçeler, İskele’de modern yaşam ve yatırım fırsatı.",
  location = "Bahçeler, İskele",
  statusTR = "Devam Eden",
  delivery = "Aralık 2028",
  heroImage = "/lagoon-verde/5.jpg",
  heroAlt = "Lagoon Verde kumsal girişli lagün havuzu, palmiyeler ve rezidans blokları",
  brochureHref = "/lagoonbrotr.pdf",
  brochureLabel = "Broşür İndir (PDF)",
  contactHref = "#fiyat-al",
  contactLabel = "İletişime Geçin",
  kicker = "DND Cyprus",
  topScrimHeight = 104, // ~header height; tweak if needed
}: Props) {
  const isPdf = /\.pdf($|\?)/i.test(brochureHref ?? "");

  return (
   <section
  aria-label={`${title} — Hero`}
  // Mobilde görünen alan tam 1 ekran (header payı eklenir); masaüstünde eskisi gibi 120vh
  className="relative min-h-[calc(100svh_+_var(--hero-offset))] md:min-h-[120vh] flex items-center"
  // Pull the hero under the sticky header so the image + scrim appear behind it
  style={
    {
      marginTop: `-${topScrimHeight}px`,
      paddingTop: `${topScrimHeight}px`,
      ["--hero-offset"]: `${topScrimHeight}px`,
    } as React.CSSProperties & Record<"--hero-offset", string>
  }
>
  {/* Background image (z-0) — sayfada önceden yüklenen (priority) tek görsel */}
  <div className="absolute inset-0 z-0">
    <Image quality={65}
      src={heroImage}
      alt={heroAlt}
      fill
      preload
      sizes="100vw"
      className="object-cover"
    />
  </div>

  {/* --- Overlays for readability --- */}
  {/* 1) Top scrim ONLY behind header (z-10, header is z-50) */}
  <div
    aria-hidden
    className="absolute top-0 left-0 right-0 z-10 pointer-events-none"
    style={{
      height: `${topScrimHeight}px`,
      background: "linear-gradient(to bottom, rgba(0,0,0,0.85), rgba(0,0,0,0))",
    }}
  />

  {/* 2) Hero-wide wash (brand + depth) (z-10 so it sits above image but below header) */}
  <div
    aria-hidden
    className="absolute inset-0 z-10 pointer-events-none"
    style={{
      background: `
        radial-gradient(60rem 30rem at 10% 0%, ${TEAL}22, transparent 70%),
        radial-gradient(60rem 30rem at 90% 100%, ${ORANGE}22, transparent 70%),
        linear-gradient(to bottom, rgba(0,0,0,0.25), rgba(0,0,0,0.60))
      `,
    }}
  />


      {/* Soft brand blobs (very subtle) */}
      <div
        aria-hidden
        className="pointer-events-none absolute -left-24 top-1/4 h-72 w-72 rounded-full blur-3xl opacity-70"
        style={{ background: `${TEAL}22` }}
      />
      <div
        aria-hidden
        className="pointer-events-none absolute -right-24 bottom-10 h-72 w-72 rounded-full blur-3xl opacity-70"
        style={{ background: `${ORANGE}20` }}
      />

      {/* Content — animasyon mount'ta başlar (whileInView beklemez) */}
      <div className="relative mx-auto max-w-6xl px-4 sm:px-6 lg:px-8 py-16 md:py-24 text-center text-white z-20">
        {/* Kicker */}
        {kicker && (
          <span
            className="inline-flex items-center text-[11px] tracking-wider uppercase px-3 py-1 rounded-full"
            style={{
              background: "rgba(255,255,255,0.12)",
              border: "1px solid rgba(255,255,255,0.25)",
              backdropFilter: "blur(8px)",
            }}
          >
            {kicker}
          </span>
        )}

        {/* Title */}
        <h1
          className="mt-4 text-4xl sm:text-5xl lg:text-6xl font-semibold leading-tight"
        >
          {title}
        </h1>

        {/* Tagline */}
        <p
          className="mt-3 max-w-2xl mx-auto text-base sm:text-lg"
          style={{ color: "rgba(255,255,255,0.88)" }}
        >
          {tagline}
        </p>

        {/* Chips */}
        <div
          className="mt-5 flex flex-wrap justify-center gap-2"
        >
          <Chip text={statusTR} color={ORANGE} />
          <Chip text={location} color="rgba(255,255,255,0.85)" neutral />
          <Chip text={`Teslim: ${delivery}`} color={TEAL} />
        </div>

        {/* CTAs */}
        <div
          className="mt-6 md:mt-8 flex flex-wrap justify-center gap-3"
        >
          <a
            href={contactHref}
            data-track="price_request_click"
            className="rounded-full px-7 py-3 text-sm font-medium transition-transform hover:-translate-y-0.5"
            style={{
              background: TEAL,
              color: "#fff",
              border: `1px solid ${TEAL}66`,
              boxShadow: `0 12px 28px ${TEAL}55`,
            }}
          >
            {contactLabel}
          </a>

          {brochureHref && (
            <a
              href={brochureHref}
              target={isPdf ? "_blank" : undefined}
              rel={isPdf ? "noopener" : undefined}
              data-track={isPdf ? "brochure_download" : undefined}
              className="rounded-full px-7 py-3 text-sm font-medium"
              style={{
                background: "rgba(255,255,255,0.12)",
                color: "#fff",
                border: "1px solid rgba(255,255,255,0.28)",
                backdropFilter: "blur(8px)",
              }}
            >
              {brochureLabel}
            </a>
          )}
        </div>
      </div>
    </section>
  );
}

/* -------- Small chip helper -------- */
function Chip({
  text,
  color,
  neutral = false,
}: {
  text: string;
  color: string;
  neutral?: boolean;
}) {
  const styles = neutral
    ? {
        background: "rgba(255,255,255,0.15)",
        border: "1px solid rgba(255,255,255,0.28)",
        color: "#fff",
      }
    : {
        background: `${color}33`,
        border: `1px solid ${color}66`,
        color: "#fff",
      };

  return (
    <span
      className="text-xs px-3 py-1 rounded-full"
      style={styles as React.CSSProperties}
    >
      {text}
    </span>
  );
}

