// app/components/mariachi/MariachiGalleryExpanding.tsx
"use client";

import React, { useMemo, useState } from "react";
import DeferredFillImage from "@/app/components/performance/DeferredFillImage";
import { m as motion, type Variants, type Easing } from "framer-motion";

const TEAL = "#27959b";
const ORANGE = "#f15c34";
const EASE: Easing = [0.22, 1, 0.36, 1] as const;

const fadeUp: Variants = {
  hidden: { opacity: 0, y: 16 },
  show: {
    opacity: 1,
    y: 0,
    transition: { duration: 0.45, ease: EASE },
  },
};

type GalleryItem = {
  src: string;   // public/ yolundan görsel
  alt?: string;
  label?: string; // (opsiyonel) alt cam şerit etiketi
};

export default function MariachiGalleryExpanding({
  title = "Galeri",
  subtitle = "Mariachi Beach Club Görselleri",
  items,
}: {
  title?: string;
  subtitle?: string;
  items?: GalleryItem[];
}) {
  // 5 görsel için örnek veri — kendi yollarınızla değiştirin
  const data: GalleryItem[] = useMemo(
    () =>
      items ?? [
        { src: "/mariachi/1.jpg", alt: "Havuz" },
        { src: "/mariachi/2.jpg", alt: "Plaj" },
        { src: "/mariachi/3.jpg", alt: "Cabanalar" },
        { src: "/mariachi/4.jpg", alt: "DJ Gecesi" },
        { src: "/mariachi/5.jpg", alt: "Kokteyller" },
      ],
    [items]
  );

  // Hover / Tap aktif panel
  const [hovered, setHovered] = useState<number | null>(null);
  const [active, setActive] = useState<number | null>(null);

  // Kart için büyüme oranı
  const growth = (i: number) => {
    // Tap ile seçilmişse onu esas al
    if (active !== null) return i === active ? 3.2 : 0.8;
    // Hover varsa ona göre
    if (hovered !== null) return i === hovered ? 3.2 : 0.8;
    // Varsayılan
    return 1;
  };

  return (
    <section
      aria-label="Mariachi Beach Club — Galeri"
      className="relative overflow-hidden"
      id ="gallery"
      style={{ background: "#ffffff", color: "#141517" }}
      data-bg="light"
    >
      {/* Sayfa arka plan dekoru — gradyanlı aura (cam hissi) */}
      <div
        aria-hidden
        className="pointer-events-none absolute -top-28 left-1/2 -translate-x-1/2 h-[28rem] w-[28rem] rounded-full blur-3xl opacity-30"
        style={{
          background:
            "radial-gradient(60% 60% at 50% 50%, rgba(39,149,155,0.22), transparent 70%)",
        }}
      />
      <div
        aria-hidden
        className="pointer-events-none absolute -bottom-24 right-1/4 h-[26rem] w-[26rem] rounded-full blur-3xl opacity-30"
        style={{
          background:
            "radial-gradient(60% 60% at 50% 50%, rgba(241,92,52,0.16), transparent 70%)",
        }}
      />

      {/* Başlık */}
      <div className="relative mx-auto max-w-7xl px-4 sm:px-6 lg:px-8 pt-12 lg:pt-16">
        <motion.div
          variants={fadeUp}
          initial="hidden"
          whileInView="show"
          viewport={{ once: false, amount: 0.35 }}
          className="max-w-3xl"
        >
          <h2 className="text-3xl sm:text-4xl lg:text-5xl font-semibold leading-tight">
            {title}
          </h2>
          <p className="mt-3 text-base sm:text-lg" style={{ color: "#141517CC" }}>
            {subtitle}
          </p>
        </motion.div>
      </div>

      {/* ==== FULL-WIDTH (full-bleed) GALERİ ==== */}
      <div
        className="relative w-screen left-1/2 -translate-x-1/2 mt-8"
        // not: bu "full-bleed" hilesi, sayfa container'ından taşarak tam ekran genişlik verir
      >
        <div
          className="group relative mx-auto"
          onMouseLeave={() => setHovered(null)}
          style={{ maxWidth: "100vw" }}
        >
          {/* Track */}
          <div
            className="flex items-stretch"
            style={{
              height: "60svh",
            }}
          >
            {data.map((g, i) => {
              const grow = growth(i);
              return (
                <div
                  key={g.src + i}
                  className="relative basis-0 min-w-0 overflow-hidden"
                  onMouseEnter={() => setHovered(i)}
                  onClick={() => setActive(active === i ? null : i)} // mobil için: dokununca sabitle
                  role="button"
                  aria-label={g.alt || `Galeri görseli ${i + 1}`}
                  style={{
                    flexGrow: grow,
                    transition: "flex-grow .55s cubic-bezier(0.22,1,0.36,1)",
                    cursor: "pointer",
                  }}
                >
                  {/* Görsel */}
                  <DeferredFillImage
                    fill
                    quality={65}
                    sizes="max(50vw, 90vh)"
                    src={g.src}
                    alt={g.alt || ""}
                    className="h-full w-full object-cover select-none"
                    draggable={false}
                    style={{
                      transform: grow > 1 ? "scale(1.06)" : "scale(1.02)",
                      transition: "transform .6s cubic-bezier(0.22,1,0.36,1)",
                    }}
                  />

                  {/* Üst cam parıltı */}
                  <div
                    aria-hidden
                    className="pointer-events-none absolute inset-0"
                    style={{
                      background:
                        grow > 1
                          ? "radial-gradient(60% 50% at 50% 0%, rgba(39,149,155,0.22), transparent 60%)"
                          : "radial-gradient(60% 40% at 50% 0%, rgba(255,255,255,0.08), transparent 60%)",
                      transition: "opacity .45s ease",
                    }}
                  />

                  {/* Alt cam şerit (etiket) */}
                  {g.label ? (
                    <div
                      className="absolute left-4 right-4 bottom-4 rounded-2xl px-4 py-2 backdrop-blur-md"
                      style={{
                        background:
                          "linear-gradient(180deg, rgba(255,255,255,0.16), rgba(255,255,255,0.10))",
                        border: "1px solid rgba(255,255,255,0.26)",
                        color: "#fff",
                        boxShadow: "0 10px 24px rgba(0,0,0,0.25)",
                      }}
                    >
                      <div className="text-sm font-medium drop-shadow">{g.label}</div>
                    </div>
                  ) : null}
                </div>
              );
            })}
          </div>
        </div>
      </div>

      {/* Küçük ipucu */}
      <div className="relative mx-auto max-w-7xl px-4 sm:px-6 lg:px-8 pb-10 lg:pb-14">
        <p className="mt-5 text-xs" style={{ color: "#14151799" }}>
          *Mobilde bir görsele dokunarak büyütüp sabitleyebilir, tekrar dokunarak varsayılan görünüme dönebilirsiniz.
        </p>
      </div>
    </section>
  );
}

// app/components/mariachi/MariachiHighlights.tsx
"use client";

import DeferredFillImage from "@/app/components/performance/DeferredFillImage";
import React, { useEffect, useMemo, useRef, useState } from "react";
import {
  m as motion,
  type Variants,
  type Easing,
  useMotionValue,
  animate,
} from "framer-motion";
import { Waves, Umbrella, Martini, Music4, Sparkles, Sun } from "lucide-react";

const TEAL = "#27959b";
const ORANGE = "#f15c34";
const EASE: Easing = [0.22, 1, 0.36, 1] as const;
const GAP = 20; // px – hem stil hem ölçümde kullanıyoruz

const fadeUp: Variants = {
  hidden: { opacity: 0, y: 16 },
  show: {
    opacity: 1,
    y: 0,
    transition: { duration: 0.45, ease: EASE },
  },
};

type Highlight = {
  title: string;
  desc?: string;
  /** Kart arka plan görseli (public/ yolundan) */
  image: string;
  icon?: React.ReactNode;
};

type Props = {
  title?: string;
  subtitle?: string;
  items?: Highlight[];
  autoPlay?: boolean;
  intervalMs?: number;
};

export default function MariachiHighlights({
  title = "Olanaklar & Ayrıcalıklar",
  subtitle = "Gün boyu plaj keyfi, cabana konforu, restoran & havuz barı ve akşam DJ performansları.",
  items,
  autoPlay = true,
  intervalMs = 4800,
}: Props) {
  /** ------- Data ------- */
  const data: Highlight[] = useMemo(
    () =>
      items ?? [
        {
          title: "Havuz & Plaj",
          desc: "Geniş güneşlenme alanları, duş ve havlu servisi.",
          image: "/mariachi/2.jpg",
          icon: <Waves className="h-5 w-5" />,
        },
        {
          title: "Cabanalar",
          desc: "Gün boyu gölgede konfor; rezervasyon önerilir.",
          image: "/mariachi/6.jpg",
          icon: <Umbrella className="h-5 w-5" />,
        },
        {
          title: "Restoran & Havuz Barı",
          desc: "Gündüz ferah tatlar, akşam imza kokteyller.",
          image: "/mariachi/3.jpg",
          icon: <Martini className="h-5 w-5" />,
        },
        {
          title: "DJ Geceleri",
          desc: "Sunset’ten geç saate uzanan canlı performanslar.",
          image: "/dj.jpg",
          icon: <Music4 className="h-5 w-5" />,
        },
        {
          title: "Spa & Wellness",
          desc: "Masaj ve bakım hizmetleri (projeye göre).",
          image: "/spa.jpg",
          icon: <Sparkles className="h-5 w-5" />,
        },
        {
          title: "Kıyı Deneyimi",
          desc: "Akdeniz esintisi ve sahil yürüyüşleri.",
          image: "/sea.jpg",
          icon: <Sun className="h-5 w-5" />,
        },
      ],
    [items]
  );

  const total = data.length;

  /** ------- Motion / State ------- */
  const x = useMotionValue(0);
  const [index, setIndex] = useState(0); // sayfa indeksi (slide indeksi değil)
  const [step, setStep] = useState(0); // px olarak bir kart + gap
  const [visibleCount, setVisibleCount] = useState(1);
  const [maxIndex, setMaxIndex] = useState(0);
  const [limits, setLimits] = useState<{ left: number; right: number }>({
    left: 0,
    right: 0,
  });
  const hoverRef = useRef(false);
  const draggingRef = useRef(false);

  /** ------- Refs for layout ------- */
  const viewportRef = useRef<HTMLDivElement | null>(null);
  const trackRef = useRef<HTMLDivElement | null>(null);

  /** ------- Helpers ------- */
  const clamp = (v: number, min: number, max: number) =>
    Math.max(min, Math.min(max, v));

  /** ------- Measure / Layout ------- */
  const measure = () => {
    const vp = viewportRef.current;
    const track = trackRef.current;
    if (!vp || !track) return;

    const slides = Array.from(track.children) as HTMLElement[];
    if (!slides.length) return;

    const firstWidth = slides[0].getBoundingClientRect().width;
    const stepPx = firstWidth + GAP;
    setStep(stepPx);

    // Toplam track genişliği
    const trackWidth =
      slides.reduce((sum, el) => sum + el.getBoundingClientRect().width, 0) +
      GAP * (slides.length - 1);

    const vpWidth = vp.getBoundingClientRect().width;

    // Aynı anda görülen kart sayısını hesapla (yaklaşık)
    const visible =
      Math.max(1, Math.floor((vpWidth + GAP - 1 /* epsilon */) / stepPx)) || 1;
    setVisibleCount(visible);

    // En sola gidilebilecek maksimum negatif x
    const maxNegative = Math.min(0, vpWidth - trackWidth);
    setLimits({ left: maxNegative, right: 0 });

    // Sayfa sayısı = maxIndex + 1
    const newMaxIndex = Math.max(0, slides.length - visible);
    setMaxIndex(newMaxIndex);

    // Mevcut index geçerliyse hizala; değilse düzelt
    const safeIndex = clamp(index, 0, newMaxIndex);
    if (safeIndex !== index) setIndex(safeIndex);

    const target = clamp(-safeIndex * stepPx, maxNegative, 0);
    x.set(target);
  };

  useEffect(() => {
    measure();
    const ro = new ResizeObserver(measure);
    if (viewportRef.current) ro.observe(viewportRef.current);
    window.addEventListener("resize", measure, { passive: true });
    return () => {
      ro.disconnect();
      window.removeEventListener("resize", measure);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [total]);

  /** ------- Navigation ------- */
  const goTo = (i: number) => {
    const vp = viewportRef.current;
    const track = trackRef.current;
    if (!vp || !track || !step) return;

    const targetIndex = clamp(i, 0, maxIndex);
    setIndex(targetIndex);
    const target = clamp(-targetIndex * step, limits.left, limits.right);
    animate(x, target, { duration: 0.55, ease: EASE });
  };

  const prev = () => goTo(index - 1);
  const next = () => goTo(index + 1);

  /** ------- Drag / Swipe ------- */
  const onDragStart = () => {
    draggingRef.current = true;
    hoverRef.current = true;
  };
  const onDragEnd = () => {
    draggingRef.current = false;
    if (!step) return;
    const current = x.get();
    const nearest = clamp(Math.round(Math.abs(current) / step), 0, maxIndex);
    goTo(nearest);
    // hover bırak
    setTimeout(() => {
      hoverRef.current = false;
    }, 80);
  };

  /** ------- Autoplay ------- */
  useEffect(() => {
    if (!autoPlay || maxIndex <= 0) return;
    const id = setInterval(() => {
      if (hoverRef.current || draggingRef.current) return;
      const nextIndex = index >= maxIndex ? 0 : index + 1;
      goTo(nextIndex);
    }, intervalMs);
    return () => clearInterval(id);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [autoPlay, intervalMs, index, maxIndex, step]);

  /** ------- UI ------- */
  const totalPages = Math.max(1, maxIndex + 1); // dot sayısı

  return (
    <section
      aria-label="Mariachi Beach Club — Öne Çıkanlar"
      className="relative overflow-hidden"
      style={{ background: "#ffffff", color: "#141517" }}
      data-bg="light"
      onMouseEnter={() => (hoverRef.current = true)}
      onMouseLeave={() => (hoverRef.current = false)}
    >
      {/* Estetik aura (cam hissi, gri yok) */}
      <div
        aria-hidden
        className="pointer-events-none absolute -top-28 left-1/2 -translate-x-1/2 h-[26rem] w-[26rem] rounded-full blur-3xl opacity-30"
        style={{
          background:
            "radial-gradient(60% 60% at 50% 50%, rgba(39,149,155,0.20), transparent 70%)",
        }}
      />
      <div
        aria-hidden
        className="pointer-events-none absolute -bottom-24 right-1/4 h-[24rem] w-[24rem] rounded-full blur-3xl opacity-30"
        style={{
          background:
            "radial-gradient(60% 60% at 50% 50%, rgba(241,92,52,0.16), transparent 70%)",
        }}
      />

      <div className="relative mx-auto max-w-7xl px-4 sm:px-6 lg:px-8 pt-12 lg:pt-16 pb-12 lg:pb-16">
        <motion.div
          variants={fadeUp}
          initial="hidden"
          whileInView="show"
          viewport={{ once: false, amount: 0.35 }}
          className="max-w-3xl"
        >
          <h2 className="text-3xl sm:text-4xl lg:text-5xl font-semibold leading-tight">
            {title}
          </h2>
          <p className="mt-3 text-base sm:text-lg" style={{ color: "#141517CC" }}>
            {subtitle}
          </p>
        </motion.div>

        {/* Carousel */}
        <div className="mt-8 relative select-none">
          {/* Oklar */}


          {/* Viewport (scrollbar YOK) */}
          <div
            ref={viewportRef}
            className="overflow-hidden"
            // Mobile kaydırmada dikey kaydırmayı engelleme: yatay drag, dikey scroll serbest
            style={{ touchAction: "pan-y" }}
          >
            {/* Track – drag/swipe açık, no scrollbar */}
            <motion.div
              ref={trackRef}
              className="flex will-change-transform"
              style={{ x, columnGap: GAP }}
              drag="x"
              dragConstraints={limits}
              dragElastic={0.08}
              dragMomentum={false}
              onDragStart={onDragStart}
              onDragEnd={onDragEnd}
              role="group"
              aria-roledescription="carousel"
              aria-label="Öne çıkanlar listesi"
            >
           {/** Kartlar */}
{data.map((card, i) => {
  const isActive = i >= index && i < index + visibleCount;
  return (
    <div
      key={card.title + i}
      // only change ↓ this line
      className="shrink-0 basis-full sm:basis-[56%] md:basis-[44%] lg:basis-[32%]"
      data-slide={i}
    >
      <motion.div
        variants={fadeUp}
        initial="hidden"
        whileInView="show"
        viewport={{ once: false, amount: 0.2 }}
        className="relative h-[360px] sm:h-[420px] rounded-[24px] overflow-hidden"
        style={{
          boxShadow: isActive
            ? `0 20px 50px rgba(0,0,0,0.15), 0 10px 26px ${TEAL}12`
            : "0 14px 32px rgba(0,0,0,0.10)",
          transform: isActive ? "scale(1.02)" : "scale(0.98)",
          transition: "transform .35s cubic-bezier(0.22,1,0.36,1)",
        }}
      >
        {/* Arka plan görseli */}
        <DeferredFillImage fill src={card.image} alt="" quality={65}
          sizes="(min-width: 1280px) 600px, (min-width: 1024px) 50vw, 100vw" className="object-cover" aria-hidden />
        {/* Üstten aşağı hafif koyuluk (okunabilirlik) */}
        <div
          className="absolute inset-0"
          style={{
            background:
              "linear-gradient(to top, rgba(0,0,0,0.45), rgba(0,0,0,0.08))",
          }}
          aria-hidden
        />
        {/* Alt cam panel */}
        <div
          className="absolute h-[160px] left-4 right-4 bottom-4 rounded-2xl p-4 sm:p-5 backdrop-blur-md"
          style={{
            background:
              "linear-gradient(180deg, rgba(255,255,255,0.16), rgba(255,255,255,0.10))",
            border: "1px solid rgba(255,255,255,0.26)",
          }}
        >
          {card.icon ? (
            <span
              className="inline-flex items-center gap-1.5 text-[11px] uppercase tracking-wide px-2.5 py-1 rounded-full"
              style={{
                background: "#fff",
                border: `1px solid ${TEAL}33`,
                color: TEAL,
                boxShadow: `0 6px 14px ${TEAL}1f`,
              }}
            >
              {card.icon} <span>Öne Çıkan</span>
            </span>
          ) : null}

          <h3 className="mt-2 text-xl font-semibold text-white drop-shadow">
            {card.title}
          </h3>
          {card.desc ? (
            <p className="mt-1.5 text-sm leading-relaxed text-white/90">
              {card.desc}
            </p>
          ) : null}
        </div>
      </motion.div>
    </div>
  );
})}

            </motion.div>
          </div>

          {/* Dots (sayfa bazlı) */}
          <div className="mt-6 flex items-center justify-center gap-2">
            {Array.from({ length: totalPages }).map((_, i) => {
              const isActive = i === index;
              return (
                <button
                  type="button"
                  key={`dot-${i}`}
                  onClick={() => goTo(i)}
                  aria-label={`Sayfa ${i + 1}`}
                  aria-current={isActive ? "true" : undefined}
                  className="h-2.5 rounded-full transition-all"
                  style={{
                    width: isActive ? 28 : 8,
                    background: isActive ? TEAL : "#fff",
                    border: `1px solid ${
                      isActive ? `${TEAL}66` : "rgba(20,21,23,0.1)"
                    }`,
                    boxShadow: isActive ? `0 6px 12px ${TEAL}22` : "none",
                  }}
                />
              );
            })}
          </div>
        </div>
      </div>
    </section>
  );
}

