heroImage = "/perla/7.jpg",
brochureHref = "#",
  contactHref = "/tr/contact",
  kicker = "DND Cyprus",
  topScrimHeight = 104, // ~header height; tweak if needed
}: Props) {
  return (
   <section
  aria-label={`${title} — Hero`}
  className="relative min-h-[120vh] flex items-center"
  // Pull the hero under the sticky header so the image + scrim appear behind it
  style={{ marginTop: `-${topScrimHeight}px`, paddingTop: `${topScrimHeight}px` }}
>
  {/* Background image (z-0) */}
  <div className="absolute inset-0 z-0">
    <Image quality={65} src={heroImage} alt={title} fill preload sizes="100vw" className="object-cover" />
  </div>

  {/* --- Overlays for readability --- */}
  {/* 1) Top scrim ONLY behind header (z-10, header is z-50) */}
  <div
    aria-hidden
    className="absolute top-0 left-0 right-0 z-10 pointer-events-none"
    style={{
      height: `${topScrimHeight}px`,
      background: "linear-gradient(to bottom, rgba(0,0,0,0.85), rgba(0,0,0,0))",
    }}
  />

  {/* 2) Hero-wide wash (brand + depth) (z-10 so it sits above image but below header) */}
  <div
    aria-hidden
    className="absolute inset-0 z-10 pointer-events-none"
    style={{
      background: `
        radial-gradient(60rem 30rem at 10% 0%, ${TEAL}22, transparent 70%),
        radial-gradient(60rem 30rem at 90% 100%, ${ORANGE}22, transparent 70%),
        linear-gradient(to bottom, rgba(0,0,0,0.25), rgba(0,0,0,0.60))
      `,
    }}
  />


      {/* Soft brand blobs (very subtle) */}
      <div
        aria-hidden
        className="pointer-events-none absolute -left-24 top-1/4 h-72 w-72 rounded-full blur-3xl opacity-70"
        style={{ background: `${TEAL}22` }}
      />
      <div
        aria-hidden
        className="pointer-events-none absolute -right-24 bottom-10 h-72 w-72 rounded-full blur-3xl opacity-70"
        style={{ background: `${ORANGE}20` }}
      />

      {/* Content */}
      <div className="relative mx-auto max-w-6xl px-4 sm:px-6 lg:px-8 py-24 text-center text-white z-20">
        {/* Kicker */}
        {kicker && (
          <span
            className="inline-flex items-center text-[11px] tracking-wider uppercase px-3 py-1 rounded-full"
            style={{
              background: "rgba(255,255,255,0.12)",
              border: "1px solid rgba(255,255,255,0.25)",
              backdropFilter: "blur(8px)",
            }}
          >
            {kicker}
          </span>
        )}

        {/* Title */}
        <h1
          className="mt-4 text-4xl sm:text-5xl lg:text-6xl font-semibold leading-tight"
        >
          {title}
        </h1>

        {/* Tagline */}
        <p
          className="mt-3 max-w-2xl mx-auto text-base sm:text-lg"
          style={{ color: "rgba(255,255,255,0.88)" }}
        >
          {tagline}
        </p>

        {/* Chips */}
        <div
          className="mt-5 flex flex-wrap justify-center gap-2"
        >
          <Chip text={statusTR} color={ORANGE} />
          <Chip text={location} color="rgba(255,255,255,0.85)" neutral />
          <Chip text={`Teslim: ${delivery}`} color={TEAL} />
        </div>

        {/* CTAs */}
        <div
          className="mt-8 flex flex-wrap justify-center gap-3"
        >
          <a
            href={contactHref}
            className="rounded-full px-7 py-3 text-sm font-medium transition-transform hover:-translate-y-0.5"
            style={{
              background: TEAL,
              color: "#fff",
              border: `1px solid ${TEAL}66`,
              boxShadow: `0 12px 28px ${TEAL}55`,
            }}
          >
            İletişime Geçin
          </a>

          {brochureHref && (
            <a
              href={brochureHref}
              className="rounded-full px-7 py-3 text-sm font-medium"
              style={{
                background: "rgba(255,255,255,0.12)",
                color: "#fff",
                border: "1px solid rgba(255,255,255,0.28)",
                backdropFilter: "blur(8px)",
              }}
            >
              Broşür İndir (PDF)
            </a>
          )}
        </div>
      </div>
    </section>
  );
}

/* -------- Small chip helper -------- */
function Chip({
  text,
  color,
  neutral = false,
}: {
  text: string;
  color: string;
  neutral?: boolean;
}) {
  const styles = neutral
    ? {
        background: "rgba(255,255,255,0.15)",
        border: "1px solid rgba(255,255,255,0.28)",
        color: "#fff",
      }
    : {
        background: `${color}33`,
        border: `1px solid ${color}66`,
        color: "#fff",
      };

  return (
    <span
      className="text-xs px-3 py-1 rounded-full"
      style={styles as React.CSSProperties}
    >
      {text}
    </span>
  );
}

// app/components/projects/Perla2Overview.tsx
"use client";

import LazyYouTube from "@/app/components/LazyYouTube";

import React from "react";
import { m as motion, Variants } from "framer-motion";

const TEAL = "#27959b";
const ORANGE = "#f15c34";

const fadeUp: Variants = {
  hidden: { opacity: 0, y: 18 },
  show: (i: number = 0) => ({
    opacity: 1,
    y: 0,
    transition: { duration: 0.48, delay: i * 0.06, ease: [0.22, 1, 0.36, 1] },
  }),
};

type Props = {
  title?: string;
  lead?: string;
  highlights?: string[];
  imagePrimary?: string;       // fallback image
  embedUrl?: string | null;    // YouTube watch or embed URL; null => use image
};

export default function Perla2Overview({
  title = "La Joya Perla Genel Bakış",
  lead = "Bahçeler, İskele’de konumlanan La Joya Perla; denize 700 m mesafe, İskele’de ilk kez uygulanan doğal görünümlü ‘sand pool’ konsepti, açık-kapalı havuzlar ve zengin sosyal alanlarıyla yıl boyu lüks ve konforu bir arada sunar.",
  highlights = [
    "İskele’de ilk ‘sand pool’ (doğal kum plajı etkisi) + açık/kapalı yüzme havuzları",
    "Spa & GYM, restoran ve havuz bar; açık hava sineması & amfitiyatro",
    "Çocuk kulübü ve oyun alanları, basketbol sahası; site içi mini market & unisex kuaför",
    "Mariachi Beach Club’a üyelik ve ayrıcalıklar (yaklaşık 700 m)",
  ],
  imagePrimary = "/perla/3.jpg",
  embedUrl = "https://www.youtube.com/watch?v=uNnqGH_QFVw",
}: Props) {
  // Normalize to privacy-enhanced embed with autoplay/mute/loop
  const YT_ID =
    /(?:v=|\.be\/)([A-Za-z0-9_-]{6,})/.exec(embedUrl ?? "")?.[1] ?? null;
  const finalEmbed = YT_ID
    ? `https://www.youtube-nocookie.com/embed/${YT_ID}?autoplay=1&mute=1&controls=0&rel=0&playsinline=1&loop=1&modestbranding=1&playlist=${YT_ID}`
    : null;

  return (
    <section
      aria-label="La Joya Perla — Genel Bakış"
      className="relative overflow-hidden pb-12 lg:pb-16"
      style={{
        background: "#fff",
        color: "#141517",
        ["--stroke"]: "rgba(20,21,23,0.08)",
      } as React.CSSProperties & Record<"--stroke", string>}
    >
      {/* soft radial accents */}


      <div className="relative mx-auto max-w-7xl px-4 sm:px-6 lg:px-8 py-16 lg:py-24">
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 lg:gap-12 items-start">
          {/* Text column */}
          <div className="lg:col-span-6">
            <motion.h2
              variants={fadeUp}
              initial="hidden"
              whileInView="show"
              viewport={{ once: false, amount: 0.35 }}
              className="text-2xl sm:text-3xl font-semibold"
            >
              {title}
            </motion.h2>

            <motion.p
              variants={fadeUp}
              initial="hidden"
              whileInView="show"
              viewport={{ once: false, amount: 0.35 }}
              custom={1}
              className="mt-3 text-base sm:text-lg leading-relaxed"
              style={{ color: "rgba(20,21,23,0.75)" }}
            >
              {lead}
            </motion.p>

            {/* Highlights */}
            <div className="mt-6 space-y-2">
              {highlights.map((h, i) => (
                <motion.div
                  key={i}
                  variants={fadeUp}
                  initial="hidden"
                  whileInView="show"
                  viewport={{ once: false, amount: 0.35 }}
                  custom={2 + i}
                  className="flex items-start gap-2"
                >
                  <span
                    aria-hidden
                    className="mt-1 inline-block h-2.5 w-2.5 rounded-full"
                    style={{ background: i % 2 === 0 ? TEAL : ORANGE }}
                  />
                  <span
                    className="text-sm sm:text-base"
                    style={{ color: "rgba(20,21,23,0.78)" }}
                  >
                    {h}
                  </span>
                </motion.div>
              ))}
            </div>

            {/* Micro chips */}
            <motion.div
              variants={fadeUp}
              initial="hidden"
              whileInView="show"
              viewport={{ once: false, amount: 0.35 }}
              custom={highlights.length + 3}
              className="mt-6 flex flex-wrap gap-2"
            >
              {[
                { label: "Aile Dostu", color: TEAL },
                { label: "Yatırıma Uygun", color: ORANGE },
                { label: "Sahil Yaşamı", color: TEAL },
              ].map((b) => (
                <span
                  key={b.label}
                  className="text-xs px-3 py-1 rounded-full"
                  style={{
                    background: `${b.color}14`,
                    color: b.color,
                    border: `1px solid ${b.color}33`,
                    backdropFilter: "blur(8px)",
                  }}
                >
                  {b.label}
                </span>
              ))}
            </motion.div>
          </div>

          {/* Media column */}
          <div className="lg:col-span-6">
            <motion.div
              variants={fadeUp}
              initial="hidden"
              whileInView="show"
              viewport={{ once: false, amount: 0.3 }}
              className="rounded-2xl overflow-hidden"
              style={{
                background:
                  "linear-gradient(180deg, rgba(255,255,255,0.8), rgba(255,255,255,0.6))",
                border: "1px solid var(--stroke)",
                boxShadow:
                  "0 12px 28px rgba(0,0,0,0.05), inset 0 1px rgba(255,255,255,0.6)",
                backdropFilter: "blur(10px)",
              }}
            >
              <div className="aspect-video bg-black">
                {finalEmbed ? (
                  <LazyYouTube
                    videoId={YT_ID!}
                    title="La Joya Perla tanıtım videosu"
                    posterAlt="La Joya Perla tanıtım videosu"
                    className="relative w-full h-full"
                    query={`autoplay=1&mute=1&controls=0&rel=0&playsinline=1&loop=1&playlist=${YT_ID}`}
                  />
                ) : (
                  <img
                    src={imagePrimary}
                    alt="Proje genel görünüm"
                    className="w-full h-full object-cover"
                    loading="lazy"
                  />
                )}
              </div>
            </motion.div>
          </div>
        </div>
      </div>

      {/* subtle underglow line with spacing below */}
      <div className="relative z-10 mt-10 mb-12">
        <div
          aria-hidden
          className="mx-auto h-[2px] w-[92%] max-w-7xl"
          style={{
            background:
              "linear-gradient(90deg, transparent, rgba(20,21,23,0.14), transparent)",
          }}
        />
      </div>
    </section>
  );
}

